do $$ begin create table auth_logs (id serial primary key, user_name text, event text, created_at timestamp default now()); insert into auth_logs (user_name,event,created_at) select 'user_'||g, 'login', now()-(random()*interval '30 days') from generate_series(1,50) g; create table api_metrics (id serial primary key, endpoint text, latency_ms int, created_at timestamp default now()); insert into api_metrics (endpoint,latency_ms,created_at) select '/api/v1/resource', (random()*500)::int, now()-(random()*interval '30 days') from generate_series(1,50) g; create table order_events (id serial primary key, order_id int, status text, created_at timestamp default now()); insert into order_events (order_id,status,created_at) select g, 'processed', now()-(random()*interval '30 days') from generate_series(1,50) g; create table payment_records (id serial primary key, amount numeric, currency text, created_at timestamp default now()); insert into payment_records (amount,currency,created_at) select round((random()*500)::numeric,2), 'usd', now()-(random()*interval '30 days') from generate_series(1,50) g; create table audit_trail (id serial primary key, action text, actor text, created_at timestamp default now()); insert into audit_trail (action,actor,created_at) select 'update', 'system', now()-(random()*interval '30 days') from generate_series(1,50) g; create table inventory_items (id serial primary key, sku text, quantity int, created_at timestamp default now()); insert into inventory_items (sku,quantity,created_at) select 'sku_'||g, (random()*100)::int, now()-(random()*interval '30 days') from generate_series(1,50) g; create table job_queue (id serial primary key, job_name text, state text, created_at timestamp default now()); insert into job_queue (job_name,state,created_at) select 'job_'||g, 'completed', now()-(random()*interval '30 days') from generate_series(1,50) g; create table feature_flags (id serial primary key, flag_name text, enabled boolean, created_at timestamp default now()); insert into feature_flags (flag_name,enabled,created_at) select 'flag_'||g, random()>0.5, now()-(random()*interval '30 days') from generate_series(1,50) g; create table system_events (id serial primary key, severity text, message text, created_at timestamp default now()); insert into system_events (severity,message,created_at) select 'info', 'event generated', now()-(random()*interval '30 days') from generate_series(1,50) g; create table usage_stats (id serial primary key, resource text, usage_count int, created_at timestamp default now()); insert into usage_stats (resource,usage_count,created_at) select 'cpu', (random()*1000)::int, now()-(random()*interval '30 days') from generate_series(1,50) g; end $$;